-- Advanced concepts: analytics view, stored function, audit trigger; transaction is in 03_queries.sql.
CREATE OR REPLACE VIEW v_topic_year_analytics AS SELECT t.name AS topic,p.year,COUNT(*) AS paper_count,ROUND(AVG(p.citation_count),2) AS avg_citations FROM papers p JOIN paper_topics pt ON pt.paper_id=p.paper_id JOIN topics t ON t.topic_id=pt.topic_id WHERE p.status='PUBLISHED' GROUP BY t.name,p.year;
CREATE OR REPLACE FUNCTION fn_upsert_paper_with_topics(p_title VARCHAR,p_abstract TEXT,p_year SMALLINT,p_venue VARCHAR,p_topics TEXT[],p_actor BIGINT) RETURNS BIGINT LANGUAGE plpgsql AS $$ DECLARE v_venue BIGINT; v_paper BIGINT; v_topic TEXT; v_topic_id BIGINT; BEGIN INSERT INTO venues(name) VALUES(p_venue) ON CONFLICT(name) DO UPDATE SET name=EXCLUDED.name RETURNING venue_id INTO v_venue; INSERT INTO papers(title,abstract,year,venue_id,uploaded_by,status) VALUES(p_title,p_abstract,p_year,v_venue,p_actor,'PUBLISHED') RETURNING paper_id INTO v_paper; FOREACH v_topic IN ARRAY p_topics LOOP INSERT INTO topics(name) VALUES(v_topic) ON CONFLICT(name) DO UPDATE SET name=EXCLUDED.name RETURNING topic_id INTO v_topic_id; INSERT INTO paper_topics(paper_id,topic_id) VALUES(v_paper,v_topic_id) ON CONFLICT DO NOTHING; END LOOP; RETURN v_paper; END; $$;
CREATE OR REPLACE FUNCTION fn_audit_paper() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN INSERT INTO audit_log(paper_id,actor_id,action,old_data,new_data) VALUES(COALESCE(NEW.paper_id,OLD.paper_id),COALESCE(NEW.uploaded_by,OLD.uploaded_by),TG_OP,to_jsonb(OLD),to_jsonb(NEW)); RETURN COALESCE(NEW,OLD); END; $$;
CREATE TRIGGER trg_paper_audit AFTER INSERT OR UPDATE OR DELETE ON papers FOR EACH ROW EXECUTE FUNCTION fn_audit_paper();
